messages.content:
{
  "message": "I can help with those exchanges and the cancellation. First, I need to verify your account.",
  "auth_request": {
    "prompt": "Please provide the email on your account. If you don’t remember it, please provide your first and last name along with your ZIP code."
  },
  "notes": [
    "Exchanges must be for variants within the same product (same product, different options).",
    "Cancellations are only possible for entire pending orders (not single items). If the skateboard is in a pending order, we can cancel that whole order; otherwise we can process a return/exchange after delivery.",
    "I’ll list all action details for your confirmation before I proceed."
  ],
  "info_needed": {
    "payment_method": {
      "preference": "Visa credit card",
      "prompt": "Please confirm the last 4 digits of the Visa card on your account you’d like to use for any price differences/refunds."
    },
    "bicycle_and_puzzle_exchange": {
      "order_id": "Please provide the order ID that includes the bicycle and the jigsaw puzzle.",
      "delivered_status": "Please confirm this order has been delivered.",
      "bicycle": {
        "current_item_details": "Optional: any notes to identify it (e.g., model/size). I will also verify from the order.",
        "target_frame_size": "What frame size would you like?"
      },
      "puzzle": {
        "current_item_details": "Optional: any notes to identify it (e.g., current piece count/difficulty/theme).",
        "constraints": "Same difficulty, +1000 pieces; prefer art theme over animals (must be a variant within the same product).",
        "flexibility": "If the exact art theme variant isn’t available within the same product, is another art variant with the same difficulty acceptable?"
      }
    },
    "camera_exchange": {
      "order_id": "Please provide the order ID that includes the camera.",
      "delivered_status": "Please confirm this order has been delivered.",
      "target_resolution": "What resolution would you like (e.g., target megapixels or the exact lower-resolution variant/model), keeping all other options the same?"
    },
    "skateboard_cancellation": {
      "order_id": "Please provide the order ID that includes the skateboard.",
      "status_note": "If that order is pending, I can cancel the entire order. If it’s already processed or delivered, we can arrange a return/exchange instead. Do you want to cancel the whole order containing the skateboard if it’s pending?"
    }
  }
}

